/**
 * Syncs runtime data files so `vite build` / gh-pages serve them without drift.
 *
 * Source of truth chain (see docs/data-pipeline.md):
 *   data/ --(npm run preprocess)--> src/data/processed/
 *         --(this script, prebuild)--> public/data/processed/
 *         --(vite build auto-copies public/)--> dist/data/processed/
 *
 * Why this script exists: `src/data/processed/*.json` is generated by
 * `npm run preprocess` and bundled via static imports, but `useInitiatives`
 * fetches `initiatives.json` + `sensors.json` at RUNTIME (not bundled).
 * Runtime files must live under `public/` so Vite copies them to `dist/`.
 * This script derives them from `src/` so the two copies never drift.
 *
 * Idempotent: files are compared by SHA-256 and only written when content
 * differs, so repeated runs don't touch mtimes or invalidate caches.
 *
 * Usage: node scripts/copy-data.mjs [--check|--verify]
 * (Called automatically via "prebuild" in package.json)
 * --check/--verify: drift detection only — exits 1 when any public/
 * copy is missing or differs from src/ (used by CI), writes nothing.
 */
import { copyFileSync, mkdirSync, existsSync, readFileSync, writeFileSync, statSync } from 'fs';
import { createHash } from 'crypto';
import { join, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = join(__dirname, '..');

// Canonical files: derived from src/ (preprocess output), published via public/.
const files = [
  { src: 'src/data/processed/initiatives.json', dest: 'public/data/processed/initiatives.json' },
  { src: 'src/data/processed/sensors.json', dest: 'public/data/processed/sensors.json' },
];

function sha256(file) {
  return createHash('sha256').update(readFileSync(file)).digest('hex');
}

const args = process.argv.slice(2);
const checkMode = args.includes('--check') || args.includes('--verify');

let copied = 0;
let upToDate = 0;
let failed = 0;
const drifted = [];

for (const { src, dest } of files) {
  const srcPath = join(root, src);
  const destPath = join(root, dest);

  if (!existsSync(srcPath)) {
    console.error(`❌ Missing source of truth: ${srcPath}`);
    console.error(`   Regenerate with: npm run preprocess`);
    failed++;
    continue;
  }

  if (existsSync(destPath) && sha256(srcPath) === sha256(destPath)) {
    console.log(`⏭️  Up-to-date: ${dest} (identical SHA-256, skipped)`);
    upToDate++;
    continue;
  }

  if (checkMode) {
    console.error(`❌ Drift detected: ${dest} is missing or differs from ${src}`);
    console.error(`   Run: node scripts/copy-data.mjs (or npm run prebuild)`);
    drifted.push(dest);
    continue;
  }

  mkdirSync(dirname(destPath), { recursive: true });
  // Write bytes (not copyFileSync) so a future --verify mode can reuse sha256().
  writeFileSync(destPath, readFileSync(srcPath));
  console.log(`✅ Synced ${src} → ${dest}`);
  copied++;
}

// Best-effort: if dist/ already exists (e.g. manual postbuild run), mirror the
// runtime files there too. During a normal `prebuild`, dist/ may not exist yet
// (or will be emptied by `vite build`, which auto-copies public/ anyway),
// so a missing dist/ is NOT an error.
// NOTE: dest lives under `public/`; strip that prefix so the mirror lands at
// `dist/data/...` (not the orphan `dist/public/data/...`).
const distDir = join(root, 'dist');
if (checkMode) {
  // Drift report only — no writes. dist/ is build output, so a stale dist/
  // is a warning, not a failure (the src→public check above is the gate).
  if (existsSync(distDir) && statSync(distDir).isDirectory()) {
    for (const { dest } of files) {
      const publicPath = join(root, dest);
      const distPath = join(root, 'dist', dest.replace(/^public\//, ''));
      if (existsSync(publicPath) && (!existsSync(distPath) || sha256(publicPath) !== sha256(distPath))) {
        console.warn(`⚠️  Stale build output: ${distPath} differs from ${dest} (rebuild to refresh).`);
      }
    }
  }
} else if (existsSync(distDir) && statSync(distDir).isDirectory()) {
  for (const { dest } of files) {
    const publicPath = join(root, dest);
    const distPath = join(root, 'dist', dest.replace(/^public\//, ''));
    if (existsSync(publicPath) && (!existsSync(distPath) || sha256(publicPath) !== sha256(distPath))) {
      mkdirSync(dirname(distPath), { recursive: true });
      copyFileSync(publicPath, distPath);
      console.log(`✅ Mirrored ${dest} to dist/`);
    }
  }
} else {
  console.log(`ℹ️  dist/ not present — skipping dist mirror (vite build copies public/ automatically).`);
}


if (failed > 0) {
  console.error(`⚠️  ${failed} data file(s) missing from source of truth.`);
  process.exit(1);
} else if (drifted.length > 0) {
  console.error(`⚠️  ${drifted.length} data file(s) drifted from source of truth (--check failed).`);
  process.exit(1);
} else {
  console.log(`✅ Data sync complete: ${copied} copied, ${upToDate} up-to-date${checkMode ? ' (--check, no writes)' : ''}.`);
}
